\"name\": \"\",\n          \"nameGap\": 15,\n          \"nameTextStyle\": {\n            \"color\": \"#B9B8CE\",\n            \"fontSize\": 12\n          },\n          \"inverse\": false,\n          \"axisLabel\": {\n            \"show\": true,\n            \"fontSize\": 12,\n            \"color\": \"#B9B8CE\",\n            \"rotate\": 0\n          },\n          \"position\": \"left\",\n          \"axisLine\": {\n            \"show\": true,\n            \"lineStyle\": {\n              \"color\": \"#B9B8CE\",\n              \"width\": 1\n            },\n            \"onZero\": true\n          },\n          \"axisTick\": {\n            \"show\": true,\n            \"length\": 5\n          },\n          \"splitLine\": {\n            \"show\": true,\n            \"lineStyle\": {\n              \"color\": \"#484753\",\n              \"width\": 1,\n              \"type\": \"solid\"\n            }\n          },\n          \"type\": \"value\"\n        },\n        \"grid\": {\n          \"show\": false,\n          \"left\": \"10%\",\n          \"top\": \"60\",\n          \"right\": \"10%\",\n          \"bottom\": \"60\"\n        },\n        \"tooltip\": {\n          \"show\": true,\n          \"trigger\": \"axis\",\n          \"axisPointer\": {\n            \"type\": \"line\"\n          }\n        },\n        \"dataset\": {\n          \"dimensions\": [\n            \"time\",\n            \"次数\",\n            \"人数\"\n          ],\n          \"source\": [\n            {\n              \"次数\": 94,\n              \"time\": \"2022-05\",\n              \"人数\": 5\n            },\n            {\n              \"次数\": 120,\n              \"time\": \"2022-06\",\n              \"人数\": 2\n            },\n            {\n              \"次数\": 118,\n              \"time\": \"2022-07\",\n              \"人数\": 5\n            },\n            {\n              \"次数\": 37,\n              \"time\": \"2022-08\",\n              \"人数\": 2\n            },\n            {\n              \"次数\": 65,\n  